var u=[{title:"حقيقة 1 شرائح السيليكون الهوائية بدل الفتيل التقليدي المؤلم ▾",body:"انتهى زمن الفتائل القطنية الطويلة التي كانت تلتصق ببطانة الأنف وتسبب ألماً شديداً عند السحب. نستخدم اليوم شرائح سيليكون طبية ناعمة ومجوّفة (Doyle Airway Splints) تحتوي على ممر هواء داخلي للتنفس الجزئي بعد العملية، ولا تلتصق بالأنسجة، فتُزال في العيادة خلال ثوانٍ بهدوء وبدون ألم يُذكر."},{title:"حقيقة 2 خدعة توازن الذقن (Profile Balancing) ▾",body:"في المنظر الجانبي للوجه، تقيّم العين حجم الأنف دائماً بالمقارنة مع بروز الذقن عبر خط Ricketts E-Line . تراجع الذقن بمقدار بضعة مليمترات يجعل الأنف الطبيعي يبدو أطول وأبرز مما هو عليه فعلياً؛ لذا فإن التعديل الهادئ للأنف مع موازنة بسيطة للذقن يعطي تناسقاً أرقى بكثير من التصغير المبالغ فيه للأنف."},{title:"حقيقة 3 هندسة الأنف الرجالي مقابل الأنف النسائي ▾",body:"تجميل الأنف الناجح يحترم الهوية التشريحية لكل شخص. في الأنف الرجالي نحافظ على جسر مستقيم قوي وزاوية أنفية شفوية بين 90° و95° بدون تقوّس أو رفع زائد للأرنبة. أما في الأنف النسائي فنعتمد جسر أنف ناعم مستقيم أو بانسيابية طفيفة وزاوية بين 95° و105° تمنح رقة وتوازناً طبيعياً مع الملامح."}],A={dorsum:{title:"جسر الأنف (Nasal Dorsum)",badge:"الخطوط الضوئية الطبيعية",body:"يتكوّن جسر الأنف من عظام الأنف في الثلث العلوي وغضاريف سقف الأنف في الثلثين السفليين، وهو المسؤول عن استقامة الأنف وانعكاس الضوء الناعم على جانبيه.",preserve:"في التقنية التحفظية بالبيزو (Push-Down / Let-Down) نخفض السنام العظمي-الغضروفي من الأسفل مع بقاء سقف الجسر سليماً كقطعة واحدة، مما يمنع التعرجات ويحفظ المظهر الطبيعي تماماً."},tip:{title:"الأرنبة والأربطة (Tip & Ligaments)",badge:"المرونة والدعم طويل الأمد",body:"تتكون الأرنبة من غضاريف مرنة دقيقة ترتبط ببعضها وبجسر الأنف عبر أربطة طبيعية (مثل رباط Scroll وPitanguy) تمنح الأرنبة ثباتها وحركتها اللطيفة عند الابتسام.",preserve:"الحفاظ على هذه الأربطة أو إعادة تثبيتها بدلاً من قص الغضاريف بإفراط يمنع هبوط الأرنبة مستقبلاً ويحفظ ملمسها المرن وغير المتحجر."},septum:{title:"الحاجز الأنفي (Nasal Septum)",badge:"المحور المركزي والتنفس",body:"الجدار الغضروفي العظمي الفاصل بين فتحتي الأنف؛ يضبط استقامة المحور الأمامي ويوفر الممر الرئيسي لتدفق الهواء بسلاسة.",preserve:"نُصحح أي انحراف مع الحفاظ على دعامة مركزية قوية (L-Strut)، ونستفيد من أي غضروف فائض كدعامة ذاتية 100% لتقوية الأرنبة."},valves:{title:"صمامات التنفس (Nasal Valves)",badge:"أولوية التنفس السليم",body:"أضيق نقطة لمرور الهواء داخل الأنف؛ وأي تصغير عشوائي غير مدروس قد يسبب انكماش الصمام وصعوبة في الشهيق العميق.",preserve:"الحفاظ على سقف الجسر يحمي زاوية الصمام الداخلي تلقائياً، وفي الحالات البنائية نستخدم دعامات غضروفية دقيقة لتوسيع مجرى الهواء."},skin:{title:"غلاف الجلد (Skin Envelope)",badge:"المعطف الذي يكشف التفاصيل",body:"يغلف الجلد الهيكل العظمي والغضروفي الجديد؛ الجلد الرقيق يُظهر التفاصيل سريعاً، بينما الجلد السميك يحتوي على غدد دهنية أكبر ويستغرق وقتاً أطول لينكمش بوضوح.",preserve:"التشريح في المستوى العميق المحافظ على الأوعية الليمفاوية يقلل التورم بشكل ملحوظ ويسرّع انكماش غلاف الجلد بأمان."}},F=[{myth:"الليزر يصغر حجم الأنف بدون جراحة",fact:"لا يوجد أي ليزر يستطيع تصغير عظام أو غضاريف الأنف. يُستخدم الليزر السطحي فقط لتحسين سماكة الجلد الدهني المتضخم (مثل حالات Rhinophyma النادرة)، أما تعديل الهيكل العظمي والغضروفي فيتطلب جراحة دقيقة."},{myth:"إزالة الفتيل بعد العملية مؤلمة جداً ولا تُحتمل",fact:"هذا كان مرتبطاً بالشاش القطني القديم. اليوم نستخدم شرائح سيليكون هوائية ناعمة ومجوّفة لا تلتصق ببطانة الأنف، وتُزال في العيادة خلال ثوانٍ بهدوء وبدون ألم حاد."},{myth:"فيلر الأنف بديل آمن ومساوٍ للجراحة",fact:"الفيلر يضيف حجماً فقط ولا يصغّر الأنف ولا يصلح التنفس، كما أنه مؤقت ويحمل حساسية وعائية عالية في شرايين الأنف؛ وإذا قررت الجراحة لاحقاً يجب إذابته تماماً قبل العملية بـ 2 إلى 4 أسابيع."},{myth:"النتيجة النهائية تظهر بالكامل بعد شهر واحد",fact:"بعد شهر يزول جزء كبير من التورم الاجتماعي، لكن التفاصيل الدقيقة للأرنبة تستغرق 6 إلى 12 شهراً لتكتمل (وقد تمتد حتى 18 شهراً في حالات الجلد السميك)."},{myth:"تشكيل العظم يسبب كدمات سوداء دائمة تحت العين",fact:"الكدمات مؤقتة وتختفي عادةً خلال أسبوع إلى 10 أيام؛ وبفضل تقنية البيزو بالموجات فوق الصوتية (Piezo Ultrasonic) التي تحمي الأوعية الدموية الدقيقة، أصبحت الكدمات أقل بكثير وأسرع زوالاً."},{myth:"الأنف يعود ليكبر أو يسقط مرة أخرى بعد سنوات",fact:"عظام وغضاريف الأنف لا تنمو مجدداً بعد البلوغ، والحفاظ على الأربطة والدعامات الغضروفية في الجراحة التحفظية والبنائية يضمن ثبات زاوية الأرنبة واستقرار الشكل على المدى الطويل."}];export{u as a,A as b,F as c};
